import { forwardRef, useImperativeHandle, useMemo, useRef, type ComponentProps } from "react";
import { Easing, Interactive, Sequence, interpolate, useCurrentFrame, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

interface ExtrudePopProps {
  className?: string;
  width?: number;
  height?: number;
  letter?: string;
  fontFamily?: string;
  fontWeight?: number | string;
  fontSize?: number;
  basePosition?: [number, number];
  maxTextWidth?: number;
  minimaxRadius?: number;
  extrudeAngleDeg?: number;
  extrudeSteps?: number;
  extrudeStartFrame?: number;
  extrudeEndFrame?: number;
  bodyColor?: string;
  faceColor?: string;
}

function ExtrudePopBase({
  className,
  width = 1920,
  height = 1080,
  letter = "WIN",
  fontFamily = "'Helvetica Neue', Helvetica, Arial, sans-serif",
  fontWeight = 700,
  fontSize = 603,
  basePosition = [959.2, 752.5],
  maxTextWidth = 1660,
  minimaxRadius = 80,
  extrudeAngleDeg = -58.6,
  extrudeSteps = 200,
  extrudeStartFrame = 0,
  extrudeEndFrame = 48,
  bodyColor = "#e8192b",
  faceColor = "#ffffff",
}: ExtrudePopProps) {
  const frame = useCurrentFrame();

  const fit = useMemo(() => {
    if (typeof document === "undefined") return 1;
    const ctx = document.createElement("canvas").getContext("2d");
    if (!ctx) return 1;
    ctx.font = `${fontWeight} ${fontSize}px ${fontFamily}`;
    const measured = ctx.measureText(letter).width;
    if (measured <= 0) return 1;
    return Math.min(1, maxTextWidth / measured);
  }, [letter, fontFamily, fontWeight, fontSize, maxTextWidth]);

  const fitFontSize = fontSize * fit;
  const fitRadius = minimaxRadius * fit;

  const radius = interpolate(
    frame,
    [extrudeStartFrame, extrudeEndFrame],
    [0, fitRadius],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.bezier(0.16, 1, 0.3, 1),
    },
  );

  const depth = radius * 2;

  const theta = (extrudeAngleDeg * Math.PI) / 180;
  const stepX = (depth * Math.sin(theta)) / extrudeSteps;
  const stepY = (depth * Math.cos(theta)) / extrudeSteps;

  const glyph = (fill: string, dx: number, dy: number, key?: string) => (
    <text
      key={key}
      x={basePosition[0] + dx}
      y={basePosition[1] + dy}
      textAnchor="middle"
      fontFamily={fontFamily}
      fontWeight={fontWeight}
      fontSize={fitFontSize}
      fill={fill}
    >
      {letter}
    </text>
  );

  return (
    <div
      className={className}
      style={{ position: "absolute", inset: 0, overflow: "hidden" }}
    >
      <svg
        width="100%"
        height="100%"
        viewBox={`0 0 ${width} ${height}`}
        preserveAspectRatio="xMidYMid meet"
        style={{ display: "block" }}
      >
        <g>
          {Array.from(
            { length: extrudeSteps + 1 },
            (_, i) => extrudeSteps - i,
          ).map((i) => glyph(bodyColor, stepX * i, stepY * i, `body-${i}`))}
        </g>

        {glyph(faceColor, stepX * extrudeSteps, stepY * extrudeSteps)}
      </svg>
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  letter: {
    type: "text-content",
    default: "WIN",
    description: "Text",
  },
  bodyColor: {
    type: "color",
    default: "#e8192b",
    description: "Body color",
  },
  faceColor: {
    type: "color",
    default: "#ffffff",
    description: "Face color",
  },
  minimaxRadius: {
    type: "number",
    min: 0,
    max: 200,
    step: 5,
    default: 80,
    description: "Extrude radius",
    hiddenFromList: false,
  },
  extrudeAngleDeg: {
    type: "number",
    min: -180,
    max: 180,
    step: 1,
    default: -58.6,
    description: "Extrude angle",
    hiddenFromList: false,
  },
  extrudeEndFrame: {
    type: "number",
    min: 10,
    max: 90,
    step: 1,
    default: 48,
    description: "Extrude ends (frame)",
    hiddenFromList: false,
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["letter","bodyColor","faceColor","minimaxRadius","extrudeAngleDeg","extrudeEndFrame","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  letter: "WIN",
  bodyColor: "#e8192b",
  faceColor: "#ffffff",
  minimaxRadius: 80,
  extrudeAngleDeg: -58.6,
  extrudeEndFrame: 48,
  speed: 1,
};

type ExtrudePopElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ExtrudePopBase>;

const ExtrudePopInner = forwardRef<
  HTMLDivElement,
  ExtrudePopElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ExtrudePop>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ExtrudePopBase
          {...(componentProps as unknown as ComponentProps<typeof ExtrudePopBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ExtrudePop = Interactive.withSchema({
  Component: ExtrudePopInner,
  componentName: "<ExtrudePop>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
